// AWI: pulihkan src foto fitur TiTAN (sementara, hapus setelah dipakai)
add_action('rest_api_init', function () {
	register_rest_route('awi/v1', '/tfix9', array(
		'methods' => 'POST',
		'permission_callback' => function () { return current_user_can('manage_options'); },
		'callback' => function () {
			global $wpdb;
			$map = array(
				'BYD TiTAN 7 DM teknologi DM-p' => 10859,
				'BYD TiTAN 7 DM suspensi DiSus-C' => 10860,
				'BYD TiTAN 7 DM mode multi-terrain' => 10861,
				'BYD TiTAN 7 DM fitur Leopard U-Turn' => 10862,
				'BYD TiTAN 7 DM fitur V2L untuk camping' => 10864,
				'BYD TiTAN 7 DM ADAS dan High Speed' => 10863,
			);
			$c = get_post_field('post_content', 10706); $o = $c; $out = array('before_empty' => substr_count($c, 'src=""'));
			foreach ($map as $alt => $id) {
				$url = wp_get_attachment_url($id);
				$out['url'][$id] = $url;
				if (!$url) continue;
				$c = str_replace('src="" alt="' . $alt, 'src="' . $url . '" alt="' . $alt, $c, $n);
				$out['fixed'][$id] = $n;
			}
			$out['after_empty'] = substr_count($c, 'src=""');
			if ($c !== $o) { $wpdb->update($wpdb->posts, array('post_content' => $c), array('ID' => 10706)); clean_post_cache(10706); $out['saved'] = 1; }
			wp_cache_flush();
			return $out;
		},
	));
});
